package com.healthcompanion.controller;
import com.healthcompanion.dto.AuthDtos.*; import com.healthcompanion.service.UserService; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") public class UserController { private final UserService service; public UserController(UserService s){service=s;} @GetMapping("/profile") public UserResponse get(Authentication a){var u=service.current(a.getName());return new UserResponse(u.getId(),u.getName(),u.getEmail());} @PutMapping("/profile") public UserResponse update(Authentication a,@Valid @RequestBody ProfileUpdateRequest req){var u=service.update(service.current(a.getName()),req);return new UserResponse(u.getId(),u.getName(),u.getEmail());} }
